css:
.sl-stats-fast-facts {
    padding-block: clamp(3rem, 6vw, 5rem);
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-stats-fast-facts .sl-mb-16 { margin-bottom: 3rem; }

.sl-stats-fast-facts .sl-facts-header {
    max-width: 600px;
}

.sl-stats-fast-facts .sl-section-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 3vw, 2.25rem);
    font-weight: 700;
    color: var(--smartlearn-text);
    margin-bottom: 1rem;
}

.sl-stats-fast-facts .sl-section-subtitle {
    font-size: 1.125rem;
    color: var(--smartlearn-text-muted);
}

/* Asymmetric Grid */
.sl-stats-fast-facts .sl-facts-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2rem;
}

@media (min-width: 992px) {
    .sl-stats-fast-facts .sl-facts-grid {
        grid-template-columns: repeat(3, 1fr);
        grid-template-rows: auto auto;
    }
}

.sl-stats-fast-facts .sl-fact-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.08));
    border-radius: var(--smartlearn-radius, 1.5rem);
    padding: 2rem;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    display: flex;
    flex-direction: column;
}

.sl-stats-fast-facts .sl-fact-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 15px 30px -5px rgba(0, 0, 0, 0.1);
}

/* Featured Large Fact */
.sl-stats-fast-facts .sl-fact-featured {
    background-color: #0f172a;
    background: linear-gradient(135deg, color-mix(in srgb, var(--smartlearn-primary) 55%, #0f172a) 0%, #0f172a 100%);
    color: #f8fafc;
    border-color: transparent;
    padding: 3rem;
}

@media (min-width: 992px) {
    .sl-stats-fast-facts .sl-fact-featured {
        grid-column: 1 / span 2;
        grid-row: 1 / span 2;
    }
}

.sl-stats-fast-facts .sl-fact-icon-wrap {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
    border-radius: var(--smartlearn-radius, 1rem);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    color: var(--smartlearn-primary);
    width: fit-content;
    padding: 1rem;
}

.sl-stats-fast-facts .sl-fact-featured .sl-fact-icon-wrap {
    background-color: rgba(255, 255, 255, 0.16);
    color: #ffffff;
}

.sl-stats-fast-facts .sl-icon-small {
    padding: 0.75rem;
    border-radius: calc(var(--smartlearn-radius, 1rem) * 0.75);
    margin-bottom: 1.25rem;
}

.sl-stats-fast-facts .sl-fact-big-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 4vw, 2.5rem);
    font-weight: 800;
    color: #ffffff;
    margin-bottom: 1.5rem;
}

.sl-stats-fast-facts .sl-fact-desc {
    font-size: 1.25rem;
    color: rgba(255, 255, 255, 0.92);
    line-height: 1.6;
    margin-bottom: 2.5rem;
}

.sl-stats-fast-facts .sl-fact-stats {
    display: flex;
    flex-wrap: wrap;
    gap: 2rem;
    margin-top: auto;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
    padding-top: 1.5rem;
}

.sl-stats-fast-facts .sl-fact-micro-stat strong {
    display: block;
    font-size: 1.75rem;
    font-weight: 800;
    margin-bottom: 0.25rem;
}

.sl-stats-fast-facts .sl-fact-micro-stat span {
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: rgba(255, 255, 255, 0.88);
}

/* Smaller Facts */
.sl-stats-fast-facts .sl-fact-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--smartlearn-text);
    margin-bottom: 0.75rem;
}

.sl-stats-fast-facts .sl-fact-desc-small {
    font-size: 1rem;
    color: var(--smartlearn-text-muted);
    line-height: 1.6;
    margin: 0;
}

@media (prefers-reduced-motion: reduce) {
    .sl-stats-fast-facts .sl-fact-card {
        transition: none;
    }
    .sl-stats-fast-facts .sl-fact-card:hover {
        transform: none;
    }
}
